from __future__ import annotations

import base64
import csv
import gzip
import hashlib
import runpy
import sys
from collections import Counter
from pathlib import Path

EXPECTED_SHA256 = "da62d07f48b5d33f9c62a0777b94685bb1e164cf25b66f5f6c27287468986e75"
EXPECTED_LAYERS = {"S1": 8, "S2": 10, "S3": 69, "S4": 15}
CANDIDATE_B64_GZ = ""

raw = gzip.decompress(base64.b64decode(CANDIDATE_B64_GZ))
actual = hashlib.sha256(raw).hexdigest()
if actual != EXPECTED_SHA256:
    raise SystemExit(f"recovered Quality102 digest mismatch: {actual}")

out = Path(".research-state/quality102-recovered.csv")
out.parent.mkdir(parents=True, exist_ok=True)
out.write_bytes(raw)
with out.open(newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
if len(rows) != 102:
    raise SystemExit(f"recovered candidate count mismatch: {len(rows)}")
layers = dict(Counter(r["layer"] for r in rows))
if layers != EXPECTED_LAYERS:
    raise SystemExit(f"recovered layer counts mismatch: {layers}")

if "--supplement-csv" in sys.argv:
    raise SystemExit("caller must not override recovered supplement input")
sys.argv.extend(["--supplement-csv", str(out)])
runpy.run_path("scripts/research_latest_v8_quality102_grosssafe.py", run_name="__main__")
